1: <!doctype html>
2: <html lang="pt-BR">
3:   <head>
4:     <meta charset="UTF-8" />
5:     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
6:     <title>Minha Primeira Cena 3D</title>
7:     <style>
8:       body {
9:         margin: 0;
10:         overflow: hidden;
11:         background-color: #000;
12:       }
13:       canvas {
14:         display: block;
15:       }
16:     </style>
17:     <!-- Importando a biblioteca Three.js via CDN -->
18:     <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
19:   </head>
20:   <body>
21:     <script>
22:       // 1. CRIANDO A CENA
23:       const scene = new THREE.Scene();
24: 
25:       // Criando o renderizador
26:       const renderer = new THREE.WebGLRenderer({ antialias: true });
27: 
28:       renderer.setSize(window.innerWidth, window.innerHeight);
29:       document.body.appendChild(renderer.domElement);
30:       
31:       const light = new THREE.DirectionalLight(0xffffff, 1.5);
32:       light.position.set(5, 5, 5);
33:       scene.add(light);
34: 
35:       const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
36:       scene.add(ambientLight);
37: 
38:       // 2. CONFIGURANDO A CÂMERA (Campo de visão, Proporção, Near, Far)
39:       const camera = new THREE.PerspectiveCamera(
40:         75,
41:         window.innerWidth / window.innerHeight,
42:         0.1,
43:         1000,
44:       );
45:       camera.position.z = 5; // Afasta a câmera no eixo Z para ver o objeto
46: 
47:       // 1. Criar as geometrias
48:       const geometria1 = new THREE.DodecahedronGeometry(1, 1, 1);
49:       const geometria2 = new THREE.TorusGeometry(0.8, 0.3, 16, 100);
50: 
51:       // 2. Definir materiais e cores
52:       const material1 = new THREE.MeshStandardMaterial({
53:         color: 0x0066ff,
54:       });
55: 
56:       const material2 = new THREE.MeshStandardMaterial({
57:         color: 0xff6600,
58:       });
59: 
60:       // 3. Construir os objetos
61:       const objeto1 = new THREE.Mesh(geometria1, material1);
62:       const objeto2 = new THREE.Mesh(geometria2, material2);
63: 
64:       // 4. Posicionar os objetos na cena
65:       objeto1.position.x = -2;
66:       objeto2.position.x = 2;
67: 
68:       // 5. Adicionar os objetos à cena
69:       scene.add(objeto1);
70:       scene.add(objeto2);
71: 
72:       // 6. Criar a animação
73:       function animate() {
74:         requestAnimationFrame(animate);
75: 
76:         objeto1.rotation.y += 0.02;
77:         objeto2.rotation.x -= 0.03;
78: 
79:         renderer.render(scene, camera);
80:       }
81: 
82:       animate();
83:     </script>
84:   </body>
85: </html>
